using FontAwesome.Sharp;
using LaboratoryDesktopApp.Controls;
using LaboratoryDesktopApp.Theme;

namespace LaboratoryDesktopApp.Forms;

public class MainForm : Form
{
    private readonly Panel content=new();private readonly Label pageTitle=new();private readonly Panel sidebar=new();
    public MainForm(){Text="Laboratory Management System";StartPosition=FormStartPosition.CenterScreen;WindowState=FormWindowState.Maximized;MinimumSize=new Size(1100,700);BackColor=AppTheme.Background;Font=AppTheme.Body;BuildLayout();Navigate("Test Catalog");}
    private void BuildLayout(){var shell=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};shell.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,238));shell.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));shell.RowStyles.Add(new RowStyle(SizeType.Absolute,72));shell.RowStyles.Add(new RowStyle(SizeType.Percent,100));shell.Controls.Add(sidebar,0,0);shell.SetRowSpan(sidebar,2);sidebar.BackColor=Color.White;sidebar.Dock=DockStyle.Fill;sidebar.Padding=new Padding(14,18,14,14);var sideLayout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,BackColor=Color.White};sideLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,68));sideLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,34));sideLayout.RowStyles.Add(new RowStyle(SizeType.Percent,100));sideLayout.Controls.Add(new Label{Text="LAB  |  Laboratory",Font=new Font("Segoe UI",14,FontStyle.Bold),ForeColor=AppTheme.Primary,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,0);sideLayout.Controls.Add(new Label{Text="WORKSPACE",Font=new Font("Segoe UI",8,FontStyle.Bold),ForeColor=AppTheme.SecondaryText,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,1);var nav=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,BackColor=Color.White};string[] pages={"Dashboard","Patients","Test Catalog","Test Categories","Test Orders","Samples","Results","Reports","Settings"};IconChar[] icons={IconChar.GaugeHigh,IconChar.Users,IconChar.Flask,IconChar.Tags,IconChar.ClipboardList,IconChar.Vial,IconChar.FileMedical,IconChar.ChartColumn,IconChar.Gear};for(int i=0;i<pages.Length;i++){var b=new Button{Text="   "+pages[i],Tag=pages[i],Width=202,Height=44,TextAlign=ContentAlignment.MiddleLeft,ImageAlign=ContentAlignment.MiddleLeft,Padding=new Padding(8,0,0,0),FlatStyle=FlatStyle.Flat,BackColor=Color.White,ForeColor=AppTheme.SecondaryText,Font=new Font("Segoe UI",10,FontStyle.Regular),Cursor=Cursors.Hand};b.FlatAppearance.BorderSize=0;b.Image=IconPictureBoxToBitmap(icons[i],AppTheme.SecondaryText);b.Click+=(_,_)=>Navigate((string)b.Tag);nav.Controls.Add(b);}sideLayout.Controls.Add(nav,0,2);sidebar.Controls.Add(sideLayout);var header=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(26,0,24,0)};header.Controls.Add(new Label{Text="Laboratory Management System",Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=AppTheme.MainText,AutoSize=true,Location=new Point(26,10)});pageTitle.Text="Test Catalog";pageTitle.Font=new Font("Segoe UI",10,FontStyle.Regular);pageTitle.ForeColor=AppTheme.SecondaryText;pageTitle.AutoSize=true;pageTitle.Location=new Point(26,39);header.Controls.Add(pageTitle);var user=new Label{Text="◉  Demo User",Font=AppTheme.Body,ForeColor=AppTheme.SecondaryText,AutoSize=true,Anchor=AnchorStyles.Top|AnchorStyles.Right};header.Resize+=(_,_)=>user.Location=new Point(header.ClientSize.Width-user.Width-24,26);header.Controls.Add(user);shell.Controls.Add(header,1,0);content.Dock=DockStyle.Fill;content.BackColor=AppTheme.Background;shell.Controls.Add(content,1,1);Controls.Add(shell);}
    private static Bitmap IconPictureBoxToBitmap(IconChar icon,Color color){var b=new Bitmap(22,22);using var g=Graphics.FromImage(b);using var f=new Font("Segoe MDL2 Assets",12);TextRenderer.DrawText(g,icon switch{IconChar.GaugeHigh=>"◉",IconChar.Users=>"♙",IconChar.Flask=>"⚗",IconChar.Tags=>"▤",IconChar.ClipboardList=>"▣",IconChar.Vial=>"♧",IconChar.FileMedical=>"▤",IconChar.ChartColumn=>"▥",_=>"⚙"},f,new Rectangle(0,0,22,22),color,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);return b;}
    private void Navigate(string page){pageTitle.Text=page;content.Controls.Clear();Control view=page switch{"Test Catalog"=>new TestCatalogControl(),"Test Categories"=>new TestCategoriesControl(),"Patients"=>new WorkflowControl("Patients"),"Test Orders"=>new WorkflowControl("Test Orders"),"Samples"=>new WorkflowControl("Samples"),"Results"=>new WorkflowControl("Results"),"Reports"=>new WorkflowControl("Reports"),"Dashboard"=>new WorkflowControl("Dashboard"),_=>new PlaceholderControl("Settings","Application preferences placeholder.")};view.Dock=DockStyle.Fill;content.Controls.Add(view);foreach(Control c in sidebar.Controls){if(c is TableLayoutPanel t&&t.GetControlFromPosition(0,2) is FlowLayoutPanel nav)foreach(Control item in nav.Controls)if(item is Button b){bool selected=Convert.ToString(b.Tag)==page;b.BackColor=selected?AppTheme.PrimaryLight:Color.White;b.ForeColor=selected?AppTheme.Primary:AppTheme.SecondaryText;}}}
}
